def metric_registry():
 rows=[]
 for category,raw in _CATS.items():
  names=raw.split()
  if len(names)!=50: raise RuntimeError(f'{category} expected 50 metrics, found {len(names)}')
  for name in names: rows.append({'category':category,'metric_number':len(rows)+1,'metric_name':name,'status':'schema_only','value':None,'source':None,'observed_at':None,'used_in_prediction':False,'notes':'Populate only from licensed timestamped evidence; missing is not zero.'})
 out=pd.DataFrame(rows)
 if len(out)!=300 or out.metric_name.duplicated().any(): raise RuntimeError('Registry must contain 300 unique metrics')
 return out
def audit_metric_data(df):
 rows=[]
 for _,m in metric_registry().iterrows():
  present=m.metric_name in df.columns; s=df[m.metric_name] if present else pd.Series(dtype=object)
  rows.append({'category':m.category,'metric_number':m.metric_number,'metric_name':m.metric_name,'column_present':present,'non_null_count':int(s.notna().sum()),'missing_count':int(len(df)-s.notna().sum()) if present else len(df),'coverage_pct':float(s.notna().mean()*100) if present and len(df) else 0.,'status':'observed' if present and s.notna().any() else 'missing_or_schema_only','used_in_prediction':False})
 return pd.DataFrame(rows)
